suspend fun <T> retryTransient(block: suspend () -> T): T {
    var delayMs = 200L
    repeat(3) { attempt ->
        try { return block() } catch (e: IOException) {
            if (attempt == 2) throw e
            delay(delayMs + Random.nextLong(0, 100))
            delayMs *= 2
        }
    }
    error("unreachable")
}
